"""Small authenticated working-memory panel; uses textContent for all user data."""
PANEL = '''<!doctype html><html lang="zh"><meta charset="utf-8"><title>对话事项与主动互动</title>
<style>body{font:16px system-ui;max-width:1100px;margin:32px auto;padding:0 20px;background:#faf9f6;color:#292821}h1{font-size:24px}section{background:white;padding:18px;margin:14px 0;border:1px solid #ddd;border-radius:10px}button,select,input{font:inherit;margin:5px;padding:6px}pre{white-space:pre-wrap;word-break:break-word}article{border-top:1px solid #ddd;padding:10px 0}.muted{color:#666}a{color:#346}</style>
<h1>对话事项与主动互动</h1><p>这里显示独立工作状态，不会修改长期记忆原文。策略模式在主配置的“记忆与主动互动”中调整。</p>
<p id="summary">读取中…</p><button id="refresh">刷新</button>
<section><h2>待回访事项</h2><div id="items"></div></section><section><h2>最近主动决策</h2><div id="decisions"></div></section><section><h2>写入与纠正记录</h2><pre id="writes"></pre></section>
<script>
const base='/api/webui/memory/interaction';const $=id=>document.getElementById(id);
const labels={open:'待回访',asked:'已问过',done:'已完成',cancelled:'已取消',uncertain:'时间待确认',expired:'已过期',off:'关闭',shadow:'观察',active:'启用'};
const time=t=>t?new Date(t*1000).toLocaleString():'未确认';
function line(parent,text){let p=document.createElement('p');p.textContent=text;parent.append(p);}
async function load(){try{let r=await fetch(base,{credentials:'same-origin'});if(!r.ok)throw Error('读取失败 '+r.status);let d=await r.json();$('summary').textContent='模式：'+(labels[d.mode]||d.mode)+'；事项 '+d.items.length+'；观察模式不改变现有回复，启用模式使用新策略';$('items').replaceChildren();for(let item of d.items){let a=document.createElement('article');line(a,(d.session_names[item.session_id]||'私聊会话')+' · '+item.title+' · '+(labels[item.status]||item.status));line(a,'原话：'+item.quote+'；来源时间：'+time(item.source_at)+'；事件：'+(item.event_day||time(item.event_at))+'；回访：'+time(item.due_at));let select=document.createElement('select');for(let s of ['open','asked','done','cancelled','uncertain','expired']){let o=document.createElement('option');o.value=s;o.textContent=labels[s]||s;o.selected=s===item.status;select.append(o)}let due=document.createElement('input');due.type='datetime-local';due.title='可选：调整回访时间';let save=document.createElement('button');save.textContent='保存纠正';save.onclick=async()=>{try{let body={status:select.value};if(due.value)body.due_at=new Date(due.value).getTime()/1000;let r=await fetch(base+'/items/'+encodeURIComponent(item.id),{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),credentials:'same-origin'});if(!r.ok)throw Error(await r.text());await load()}catch(e){alert(e.message)}};a.append(select,due,save);$('items').append(a)}$('decisions').replaceChildren();for(let item of d.decisions.slice(0,30)){let a=document.createElement('article');let detail=JSON.parse(item.detail);line(a,time(item.created_at)+' · '+item.status+' · '+item.reason);line(a,'话题：'+detail.topic+'；静默 '+detail.silence_seconds+' 秒；每日软预算 '+detail.daily_target);$('decisions').append(a)}$('writes').textContent=d.writes.map(x=>time(x.created_at)+' '+x.status+' '+x.detail).join('\\n')}catch(e){$('summary').textContent=e.message}}
$('refresh').onclick=load;load();
</script></html>'''
